const {fitDataAsync, OPTIMIZERS} = DataScience;
const dimensions = 50;
const epochs = 1000;
const batchSize = 100;
const status = document.createElement("div");
status.style.maxWidth = "280px";
status.style.whiteSpace = "normal";
status.style.overflowWrap = "anywhere";
status.textContent = "Loading MNIST...";
const image = IO.paintMNIST(new Float32Array(28 * 28));
let pca;
let network;
let ready = false;
let failed = false;

const drawing = IO.drawMNIST({
    onSubmit: data => {
        if (!ready) {
            if (!failed) status.textContent = "Still training; submit again when ready.";
            return;
        }
        try {
            const coordinates = network.eval(pca.proj(data));
            if (coordinates.some(value => !Number.isFinite(value))) throw new Error("Autoencoder produced non-finite coordinates");
            image.update(new Float32Array(pca.gen(coordinates).toArray()));
            status.textContent = "Showing the autoencoder reconstruction.";
        } catch (error) {
            console.error("Could not reconstruct image:", error);
            status.textContent = `Could not reconstruct image: ${error.message}`;
        }
    },
});
const displayImage = () => {
    const canvas = image.toVisual().value()[0];
    canvas.DOM.style.display = "block";
    return canvas;
};
const ui = IO.UI(
    {type: "canvas", value: () => status},
    {type: "canvas", value: () => drawing},
    {type: "canvas", value: displayImage},
);

const initialize = async () => {
    const samples = await IO.loadMNIST();
    if (samples.length <= dimensions) throw new Error("At least 51 MNIST images are required");
    status.textContent = "Computing PCA...";
    await new Promise(resolve => setTimeout(resolve, 0));
    pca = PCA.new(samples, dimensions);
    const coordinates = samples.map(sample => pca.proj(sample));
    if (coordinates.some(point => point.some(value => !Number.isFinite(value)))) {
        throw new Error("PCA produced non-finite coordinates");
    }
    status.textContent = "Preparing autoencoder...";
    await new Promise(resolve => setTimeout(resolve, 0));
    network = NeuralNet.builder()
        .input(dimensions)
        .layer(64)
        .layer(dimensions, NeuralNet.ACTIVATIONS.linear)
        .build();
    console.log(`Training autoencoder on ${coordinates.length} PCA projections with random mini-batches of ${Math.min(batchSize, coordinates.length)}.`);
    const {theta} = await fitDataAsync(coordinates, coordinates, network.model, {
        epochs,
        batch: batchSize,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.01}),
        continuationEvery: 10,
        continuationFn: ({epoch, loss}) => {
            const progress = `Training autoencoder: ${epoch + 1}/${epochs} (mini-batch loss ${loss.toFixed(2)})`;
            status.textContent = progress;
            console.log(progress);
        },
    });
    network.setWeights(theta);
    ready = true;
    status.textContent = "Ready. Draw an image, then submit.";
    console.log("Autoencoder training complete.");
};
setTimeout(() => {
    initialize().catch(error => {
        failed = true;
        console.error("Could not initialize autoencoder:", error);
        status.textContent = `Could not initialize autoencoder: ${error.message}`;
    });
}, 0);
ui;
